beginning.embedded_functions:
//each function name should be prefixed by em_

//whether the version token [v, end) is HTTP/1.0 or HTTP/1.1
static inline bool em_http_is_valid_version( const char *v, const char *end ){
	return ( end - v == 8 && (memcmp( v, "HTTP/1.0", 8 ) == 0 || memcmp( v, "HTTP/1.1", 8 ) == 0) );
}

/**
 * Check the HTTP version of the HTTP/1.x message that starts the TCP payload:
 * - a status line starts with the version: "HTTP/1.1 200 OK"
 * - a request line ends with it: "GET / HTTP/1.1" followed by CRLF
 * Only the first line of the payload is read, so text in a message body
 * is never taken for a start line.
 *
 * Return:
 * - 1: the start line carries a version other than HTTP/1.0 and HTTP/1.1,
 *      e.g., "HTTP/1.01" or "HTTP/1.2"
 * - 0: otherwise, including the HTTP/2 connection preface "PRI * HTTP/2.0"
 */
static inline int em_check_version_http( const char *str ){
	const char *end, *eol, *v, *c;

	if( str == NULL )
		return 0;
	end = str + mmt_mem_size( str );

	eol = memchr( str, '\n', end - str );
	if( eol == NULL )
		return 0;  //no complete first line
	if( eol > str && eol[-1] == '\r' )
		eol --;

	//status line: the version is the first token
	if( eol - str >= 5 && memcmp( str, "HTTP/", 5 ) == 0 ){
		for( v = str; v < eol && *v != ' '; v++ )
			;
		return !em_http_is_valid_version( str, v );
	}

	//request line: the version is the last token, after the last space
	for( c = eol; c > str && c[-1] != ' '; c-- )
		;
	if( c == str || eol - c < 5 || memcmp( c, "HTTP/", 5 ) != 0 )
		return 0;  //not an HTTP/1.x request line
	if( eol - str == 14 && memcmp( str, "PRI * HTTP/2.0", 14 ) == 0 )
		return 0;  //HTTP/2 connection preface (RFC 9113, section 3.4)
	return !em_http_is_valid_version( c, eol );
}
